nextflow_process {
    name "Native EVOEF2 registry module"
    script "../main.nf"
    process "EVOEF2"
    tag "evoef2"
    topics "versions"

    test("RepairStructure") {
        when {
            process {
                """
                input[0] = tuple([id: "example"], file("${moduleTestDir}/data/complex.pdb"), null)
                input[1] = "RepairStructure"
                input[2] = ""
                """
            }
        }
        then {
            assert process.success
            assert topics.versions.any { it.contains("evoef2") && it.contains("2") }
            assert process.trace.tasks().size() == 1
            assert process.out.results.size() == 1
            assert process.out.results[0][0] == [id: 'example']
            def folder = path(process.out.results[0][1])
            assert folder.resolve("evoef2.log").size() > 0
            def atoms = folder.resolve("input_Repair.pdb").readLines().findAll { it.startsWith("ATOM  ") }
            assert atoms.size() > 2500
            assert atoms.collect { it.substring(21,22) }.toSet() == ["A","B","E"].toSet()
        }
    }

    test("BuildMutant") {
        when {
            process {
                """
                input[0] = tuple([id: "example"], file("${moduleTestDir}/data/complex.pdb"), file("${moduleTestDir}/data/mutants.txt"))
                input[1] = "BuildMutant"
                input[2] = ""
                """
            }
        }
        then {
            assert process.success
            assert topics.versions.any { it.contains("evoef2") && it.contains("2") }
            assert process.trace.tasks().size() == 1
            assert process.out.results.size() == 1
            assert process.out.results[0][0] == [id: 'example']
            def folder = path(process.out.results[0][1])
            assert folder.resolve("evoef2.log").size() > 0
            def lines1 = folder.resolve("input_Model_0001.pdb").readLines().findAll { it.startsWith("ATOM  ") }
            assert lines1.collect { it.substring(21,22) }.toSet() == ["A","B","E"].toSet()
            assert lines1.findAll { it.substring(21,22) == "B" && it.substring(22,26).trim() == "26" }.collect { it.substring(17,20) }.toSet() == ["GLU"].toSet()
            def lines2 = folder.resolve("input_Model_0002.pdb").readLines().findAll { it.startsWith("ATOM  ") }
            assert lines2.collect { it.substring(21,22) }.toSet() == ["A","B","E"].toSet()
            assert lines2.findAll { it.substring(21,22) == "B" && it.substring(22,26).trim() == "26" }.collect { it.substring(17,20) }.toSet() == ["GLY"].toSet()
        }
    }

    test("OptimizeHydrogen") {
        when {
            process {
                """
                input[0] = tuple([id: "example"], file("${moduleTestDir}/data/complex.pdb"), null)
                input[1] = "OptimizeHydrogen"
                input[2] = ""
                """
            }
        }
        then {
            assert process.success
            assert topics.versions.any { it.contains("evoef2") && it.contains("2") }
            assert process.trace.tasks().size() == 1
            assert process.out.results.size() == 1
            assert process.out.results[0][0] == [id: 'example']
            def folder = path(process.out.results[0][1])
            assert folder.resolve("evoef2.log").size() > 0
            def atoms = folder.resolve("input_OptH.pdb").readLines().findAll { it.startsWith("ATOM  ") }
            assert atoms.size() > 2500
            assert atoms.collect { it.substring(21,22) }.toSet() == ["A","B","E"].toSet()
        }
    }

    test("ComputeStability") {
        when {
            process {
                """
                input[0] = tuple([id: "example"], file("${moduleTestDir}/data/complex.pdb"), null)
                input[1] = "ComputeStability"
                input[2] = ""
                """
            }
        }
        then {
            assert process.success
            assert topics.versions.any { it.contains("evoef2") && it.contains("2") }
            assert process.trace.tasks().size() == 1
            assert process.out.results.size() == 1
            assert process.out.results[0][0] == [id: 'example']
            def folder = path(process.out.results[0][1])
            assert folder.resolve("evoef2.log").size() > 0
            def totals = folder.resolve("evoef2.log").readLines().findAll { it ==~ /\s*Total\s*=.*/ }
            assert totals.size() == 1
            assert Double.isFinite(totals[0].split("=")[1].trim().toDouble())
        }
    }

    test("ComputeBinding") {
        when {
            process {
                """
                input[0] = tuple([id: "example"], file("${moduleTestDir}/data/complex.pdb"), null)
                input[1] = "ComputeBinding"
                input[2] = "AB,E"
                """
            }
        }
        then {
            assert process.success
            assert topics.versions.any { it.contains("evoef2") && it.contains("2") }
            assert process.trace.tasks().size() == 1
            assert process.out.results.size() == 1
            assert process.out.results[0][0] == [id: 'example']
            def folder = path(process.out.results[0][1])
            assert folder.resolve("evoef2.log").size() > 0
            def totals = folder.resolve("evoef2.log").readLines().findAll { it ==~ /\s*Total\s*=.*/ }
            assert totals.size() == 1
            assert Double.isFinite(totals[0].split("=")[1].trim().toDouble())
        }
    }

    test("Reject empty coordinates") {
        when {
            process {
                """
                input[0] = tuple([id: "example"], file("${moduleTestDir}/data/empty.pdb"), null)
                input[1] = "RepairStructure"
                input[2] = ""
                """
            }
        }
        then {
            assert process.failed
            assert process.errorReport.contains("PDB has no ATOM records")
        }
    }

    test("Reject an unsupported command") {
        when {
            process {
                """
                input[0] = tuple([id: "example"], file("${moduleTestDir}/data/complex.pdb"), null)
                input[1] = "UnknownCommand"
                input[2] = ""
                """
            }
        }
        then {
            assert process.failed
            assert process.errorReport.contains("Unsupported")
        }
    }

    test("Reject missing mutation list") {
        when {
            process {
                """
                input[0] = tuple([id: "example"], file("${moduleTestDir}/data/complex.pdb"), null)
                input[1] = "BuildMutant"
                input[2] = ""
                """
            }
        }
        then {
            assert process.failed
            assert process.errorReport.contains("BuildMutant requires mutant_file")
        }
    }

    test("Reject missing binding groups") {
        when {
            process {
                """
                input[0] = tuple([id: "example"], file("${moduleTestDir}/data/complex.pdb"), null)
                input[1] = "ComputeBinding"
                input[2] = ""
                """
            }
        }
        then {
            assert process.failed
            assert process.errorReport.contains("ComputeBinding requires two explicit chain groups")
        }
    }

    test("Propagate invalid mutation failure") {
        when {
            process {
                """
                input[0] = tuple([id: "example"], file("${moduleTestDir}/data/complex.pdb"), file("${moduleTestDir}/data/invalid_mutants.txt"))
                input[1] = "BuildMutant"
                input[2] = ""
                """
            }
        }
        then {
            assert process.failed
        }
    }

    test("Stub creates only a labeled placeholder") {
        options "-stub-run"
        when {
            process {
                """
                input[0] = tuple([id: "example"], file("${moduleTestDir}/data/complex.pdb"), null)
                input[1] = "RepairStructure"
                input[2] = ""
                """
            }
        }
        then {
            assert process.success
            def folder = path(process.out.results[0][1])
            assert folder.resolve("evoef2.log").text.contains("no scientific calculation performed")
        }
    }

    test("Reject missing PDB chains in binding groups") {
        when {
            process {
                """
                input[0] = tuple([id: "example"], file("${moduleTestDir}/data/complex.pdb"), null)
                input[1] = "ComputeBinding"
                input[2] = "A,E"
                """
            }
        }
        then {
            assert process.failed
            assert process.errorReport.contains("Binding groups must partition all PDB chains exactly once")
        }
    }

    test("Reject unknown chains in binding groups") {
        when {
            process {
                """
                input[0] = tuple([id: "example"], file("${moduleTestDir}/data/complex.pdb"), null)
                input[1] = "ComputeBinding"
                input[2] = "AB,Z"
                """
            }
        }
        then {
            assert process.failed
            assert process.errorReport.contains("Binding groups must partition all PDB chains exactly once")
        }
    }
}

tower.enabled = false
process.shell = ['/bin/bash', '-euo', 'pipefail']
process.cpus = 1
process.memory = '2 GB'
process.time = '10 min'
process.errorStrategy = 'terminate'
profiles {
    docker {
        docker.enabled = true
        docker.runOptions = '--platform linux/amd64'
    }
}
